import { ProjectionBars } from "@langwatch/charts";

export default function Widget() {
  const { data, isLoading, isError, error } = LW.useChartQuery("main", {});
  if (isError) return <div style={{ fontSize: 11, color: "#b00" }}>{error.message}</div>;
  if (isLoading || data === null) return <div style={{ fontSize: 11, color: "#666" }}>Loading…</div>;
  if (data.length === 0) return <div style={{ fontSize: 11, color: "#666" }}>No data in this window.</div>;

  // The last bucket returned by the query is treated as "the projection
  // point": in this window it is usually a partial (in-progress) day, so
  // marking it as projected communicates "still filling in" rather than
  // implying it's a complete, comparable day like the ones before it.
  const lastBucket = data[data.length - 1].bucket;
  const costs = data.map(function (row) { return Number(row.cost || 0); }).sort(function (a, b) { return a - b; });
  const median = costs[Math.floor(costs.length / 2)] || 0;
  const budget = median * 2;

  return (
    <div style={{ height: "100%" }}>
      <ProjectionBars
        data={data}
        x="bucket"
        y="cost"
        projectionFrom={lastBucket}
        budget={budget}
      />
    </div>
  );
}
